header-node.pseudocode:
class Node:
    def __init__(self, data=None):
        self.data, self.next = data, None

def make_list():
    return Node()  # 헤더 노드: 데이터 없음

def insert_front(head, x):
    node = Node(x)
    node.next = head.next  # 공백 리스트여도 동일 코드
    head.next = node

def delete(head, x):
    prev = head  # 첫 노드 삭제도 특례 없음
    while prev.next and prev.next.data != x:
        prev = prev.next
    if prev.next:
        prev.next = prev.next.next

heap-sort.pseudocode:
def sift_down(A, i, n):
    while 2 * i + 1 < n:
        c = 2 * i + 1  # 왼쪽 자식
        if c + 1 < n and A[c + 1] > A[c]:
            c += 1  # 더 큰 자식 선택
        if A[i] >= A[c]:
            break  # 힙 성질 만족
        A[i], A[c] = A[c], A[i]
        i = c

def heap_sort(A):
    n = len(A)
    for i in range(n // 2 - 1, -1, -1):
        sift_down(A, i, n)  # Build-Max-Heap: O(n)
    for end in range(n - 1, 0, -1):
        A[0], A[end] = A[end], A[0]  # 최댓값을 끝으로
        sift_down(A, 0, end)  # 줄어든 힙 복원
    return A

heapify.pseudocode:
def sift_down(A, i, n):  # 최대 힙, O(log n)
    while True:
        l, r = 2 * i + 1, 2 * i + 2
        big = i
        if l < n and A[l] > A[big]:
            big = l
        if r < n and A[r] > A[big]:
            big = r
        if big == i:  # 부모가 가장 큼 → 종료
            return
        A[i], A[big] = A[big], A[i]
        i = big  # 교환한 자식 위치로 내려감

def build_heap(A):  # 전체 O(n)
    n = len(A)
    for i in range(n // 2 - 1, -1, -1):  # 마지막 내부 노드부터
        sift_down(A, i, n)

heuristic-miner.pseudocode:
def heuristic_miner(log, threshold=0.9):
    # log: [['a', 'b', 'c'], ['a', 'c', 'b'], ...]
    follows = {}  # (a, b): a 바로 뒤 b가 나온 횟수
    for trace in log:
        for a, b in zip(trace, trace[1:]):
            follows[(a, b)] = follows.get((a, b), 0) + 1
    acts = {x for t in log for x in t}
    edges = {}
    for a in acts:
        for b in acts:
            ab = follows.get((a, b), 0)
            ba = follows.get((b, a), 0)
            if a == b:
                dep = ab / (ab + 1)  # 길이 1 루프
            else:
                dep = (ab - ba) / (ab + ba + 1)  # -1~1
            if dep >= threshold:  # 빈도 낮은 노이즈 제거
                edges[(a, b)] = dep
    return edges  # 의존 그래프의 간선
